from pathlib import Path

# bws-nowindow-shim: on Windows every child starts with CREATE_NO_WINDOW. A harness driver runs detached (no
# console), and with Windows Terminal as the default terminal each console exe started without a console
# opens a new terminal window. The flag is ignored with DETACHED_PROCESS / CREATE_NEW_CONSOLE, so those calls are left as they are.
if os.name == "nt":
    _PopenReal = subprocess.Popen

    class _PopenNoWindow(_PopenReal):
        def __init__(self, *args, **kwargs):
            flags = kwargs.get("creationflags", 0)
            if not flags & 0x00000018:  # DETACHED_PROCESS | CREATE_NEW_CONSOLE
                kwargs["creationflags"] = flags | 0x08000000  # CREATE_NO_WINDOW
            super().__init__(*args, **kwargs)

    subprocess.Popen = _PopenNoWindow

HERE = Path(__file__).resolve().parent
CFG = json.loads((HERE / "loop.json").read_text(encoding="utf-8"))
ROOT = (HERE / CFG.get("repoRootFromHarness", "../..")).resolve()
SYSTEM_PROMPT = HERE / "worker-system-prompt.md"
USER = CFG.get("user", "the user")
GATE_MARKER = "GATE-RUNNING.json"  # written by `harness.py gate` in the unit folder while the gate runs

TASK_RE = re.compile(r"^- \[( |x|~)\] (T\d+)\b(.*)$")
NEED_RE = re.compile(r"^- \[( |x)\] (N\d+)\b(.*)$")


# ---------------------------------------------------------------- helpers

def now() -> str:
    return dt.datetime.now().isoformat(timespec="seconds")


def log(msg: str) -> None:
    print(f"[harness {now()}] {msg}", flush=True)


def trim(text: str, n: int = 170) -> str:
    return text if len(text) <= n else text[: n - 1].rstrip() + "…"


def harness_dir(dry: bool) -> Path:
    d = ROOT / CFG["harnessDir"]
    return d / "dryrun-state" if dry else d


def state_path(dry: bool) -> Path:
    return harness_dir(dry) / "state.json"


def units(dry: bool) -> list[dict]:
    return [CFG["dryRun"]] if dry else CFG["units"]


def unit_cfg(uid: str) -> dict:
    for u in CFG["units"] + [CFG["dryRun"]]:
        if u["id"] == uid:
            return u
    raise SystemExit(f"unknown unit {uid}")


def worker_cfg(u: dict) -> dict:
    """Global worker settings, overridden per unit (backend, model, tier, subagentModel, effort...)."""
    w = dict(CFG["worker"])
    w.update(u.get("worker", {}))
    return w


def for_backend(v, backend: str):
    """A setting is either one value for every backend or a {backend: value} map."""
    return v.get(backend) if isinstance(v, dict) else v


def ladder(w: dict) -> list[str]:
    return w.get("tierLadder") or list(w.get("tiers", {}))


def unit_tier(w: dict, bs: dict | None, dry: bool) -> str | None:
    """The unit's starting tier plus any escalation steps recorded in state.json."""
    if w.get("model"):
        return None  # an explicit model always wins and turns tiers (and escalation) off for the unit
    lad = ladder(w)
    tier = lad[0] if dry and lad else w.get("tier")  # dry runs always use the cheapest tier
    if tier and bs and bs.get("tierBump") and tier in lad:
        tier = lad[min(lad.index(tier) + bs["tierBump"], len(lad) - 1)]
    return tier


def resolve_worker(u: dict, bs: dict | None, dry: bool) -> dict:
    """worker_cfg with the tier resolved to this backend's concrete model, effort and subagent model."""
    w = worker_cfg(u)
    b = w["backend"]
    tier = unit_tier(w, bs, dry)
    w["resolvedTier"] = tier
    if tier:
        spec = for_backend(w.get("tiers", {}).get(tier, {}), b) or {}
        if isinstance(spec, str):
            spec = {"model": spec}
        w["model"] = spec.get("model")
        for k in ("effort", "subagentModel", "subagentEffort"):
            if spec.get(k):
                w[k] = spec[k]
    for k in ("model", "effort", "subagentModel", "subagentEffort"):
        w[k] = for_backend(w.get(k), b)
    return w


def can_escalate(w: dict, bs: dict, dry: bool) -> bool:
    if dry:
        return False  # a dry run proves the loop; it never climbs to a costlier model
    tier, lad = unit_tier(w, bs, False), ladder(w)
    return bool(w.get("escalate") and tier in lad and lad.index(tier) < len(lad) - 1)


def fresh_state(dry: bool) -> dict:
    return {
        "title": CFG["title"], "dryRun": dry,
        "driver": {"status": "IDLE", "pid": None, "message": "", "updated": now(), "desired": "idle"},
        "current": None,
        "order": [u["id"] for u in units(dry)],
        "units": {u["id"]: {"name": u["name"], "status": "PENDING", "folder": None, "sessions": 0,
                            "noProgress": 0, "crashes": 0, "verifyFails": 0, "lastExit": None,
                            "costUsd": 0.0, "tokens": 0, "heartbeat": None, "message": "",
                            "workerPid": None} for u in units(dry)},
    }


def _read_json(p: Path) -> dict | None:
    """A state file, or None when it is missing, empty, NUL-filled by a crash, or otherwise unreadable."""
    raw = b""
    for attempt in range(8):  # Windows: the driver's rename or AV can hold the file for a moment
        try:
            raw = p.read_bytes()
            break
        except FileNotFoundError:
            return None
        except OSError:
            time.sleep(0.25)
    if not raw.strip(b"\x00 \r\n\t"):
        return None
    try:
        d = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return None
    return d if isinstance(d, dict) and "units" in d and "driver" in d else None


def load_state(dry: bool, write: bool = False) -> dict:
    """state.json, else its .bak (a hard crash can zero-fill the live file), else a rebuild from the run folders.
    A rebuilt state lists every unit PENDING with its folder: the driver then verifies DONE units from disk,
    and the gate receipts make that verification cheap. Only commands that own the state (run, stop, answer,
    start) write a recovery back (write=True); observers (status, supervise, gate) never overwrite a live
    driver's state with an older .bak."""
    p = state_path(dry)
    bak = p.with_suffix(".bak")
    state = _read_json(p)
    if state is None and (p.exists() or bak.exists()):
        state = _read_json(bak)
        if state is not None:
            log(f"state.json was unreadable (crash?); restored from {bak.name} "
                f"(saved {state['driver'].get('updated')})")
        else:
            state = fresh_state(dry)
            for u in units(dry):
                folder = unit_folder(u, dry)
                if (folder / "TASKS.md").exists():
                    state["units"][u["id"]]["folder"] = folder.relative_to(ROOT).as_posix()
            state["driver"]["message"] = "state rebuilt from the run folders after both state files were unreadable"
            log("state.json and its .bak were unreadable; rebuilt from the run folders (costs and session counts "
                "are lost; units are re-verified from disk)")
        if write:
            if p.exists():
                shutil.copy(p, p.with_suffix(".corrupt"))
            save_state(state, dry)
    if state is None:
        state = fresh_state(dry)
    state["driver"].setdefault("desired", "idle")
    for u in units(dry):  # units added to loop.json after the state was created
        if u["id"] not in state["units"]:
            state["order"].append(u["id"])
            state["units"][u["id"]] = fresh_state(dry)["units"][u["id"]]
    return state


_lock = threading.Lock()


def _write_durable(p: Path, text: str) -> None:
    """Write via a temp file, fsync it, then rename. Windows: a reader (the board, AV) can hold the target for a
    moment, so the rename retries."""
    tmp = p.with_name(p.name + ".tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(text)
        f.flush()
        os.fsync(f.fileno())
    for attempt in range(40):
        try:
            os.replace(tmp, p)
            return
        except PermissionError:
            if attempt == 39:
                raise
            time.sleep(0.25)


def save_state(state: dict, dry: bool) -> None:
    with _lock:
        p = state_path(dry)
        p.parent.mkdir(parents=True, exist_ok=True)
        state["driver"]["updated"] = now()
        text = json.dumps(state, indent=2)
        _write_durable(p, text)
        _write_durable(p.with_suffix(".bak"), text)  # the fallback when a crash zero-fills state.json


def pid_alive(pid: int | None) -> bool:
    if not pid:
        return False
    if os.name == "nt":
        k = ctypes.windll.kernel32
        h = k.OpenProcess(0x1000, False, pid)
        if not h:
            return False
        code = ctypes.c_ulong()
        k.GetExitCodeProcess(h, ctypes.byref(code))
        k.CloseHandle(h)
        return code.value == 259
    try:
        os.kill(pid, 0)
        return True
    except OSError:
        return False


def proc_image(pid: int | None) -> str:
    """The executable name of a live pid (lower case), or "" when it is gone or unreadable."""
    if not pid:
        return ""
    if os.name == "nt":
        k = ctypes.windll.kernel32
        h = k.OpenProcess(0x1000, False, pid)  # PROCESS_QUERY_LIMITED_INFORMATION
        if not h:
            return ""
        buf, size = ctypes.create_unicode_buffer(1024), ctypes.c_ulong(1024)
        ok = k.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size))
        k.CloseHandle(h)
        return Path(buf.value).name.lower() if ok else ""
    try:
        return Path(os.readlink(f"/proc/{pid}/exe")).name.lower()
    except OSError:
        return ""


def is_ours(pid: int | None, kind: str) -> bool:
    """A recorded pid still belongs to the harness. Windows reuses pids, so a pid from an old state.json can now be
    any process: never kill it, and never treat it as a live driver, unless its executable fits."""
    if not pid_alive(pid):
        return False
    img = proc_image(pid)
    if kind == "driver":
        return img.startswith("python")
    exes = {Path(b.get("exe", "")).name.lower() for b in CFG["worker"].get("backends", {}).values() if b.get("exe")}
    return img in exes or img.startswith(("python", "claude", "codex", "node"))


def kill_tree(pid: int) -> None:
    if os.name == "nt":
        subprocess.run(["taskkill", "/T", "/F", "/PID", str(pid)], capture_output=True)
    else:
        try:
            os.killpg(os.getpgid(pid), 9)
        except OSError:
            pass


def git(*args: str, check: bool = True) -> str:
    r = subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True, encoding="utf-8", errors="replace")
    if check and r.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
    return r.stdout.strip()


def git_enabled() -> bool:
    return bool(CFG.get("git", {}).get("enabled", True))


# ---------------------------------------------------------------- task sources

def expand(ids: list[str]) -> list[str]:
    out = []
    for item in ids:
        m = re.fullmatch(r"(.*?-)(\d+)\.\.(\d+)", item)
        if m:
            w = len(m.group(2))
            out += [f"{m.group(1)}{i:0{w}d}" for i in range(int(m.group(2)), int(m.group(3)) + 1)]
        else:
            out.append(item)
    return out


def spec_rows(ts: dict) -> dict[str, list[str]]:
    """Markdown table rows whose first cell is an ID matching ts['idPattern']."""
    row_re = re.compile(r"^\|\s*(" + ts["idPattern"] + r")\s*\|(.+)\|\s*$")
    rows: dict[str, list[str]] = {}
    for spec in ts["specs"]:
        for line in (ROOT / spec).read_text(encoding="utf-8").splitlines():
            m = row_re.match(line)
            if m:
                rows[m.group(1)] = [c.strip().replace("**", "") for c in m.group(2).split("|")]
    return rows


def render_id_task(ts: dict, rid: str, cells: list[str]) -> str:
    templates = ts.get("templates", {})
    tpl = next((t for p, t in templates.items() if p != "*" and rid.startswith(p)), templates.get("*", "{c0}"))
    cells = cells + [""] * 4
    return f"[{rid}] " + tpl.format(**{f"c{i}": trim(c, 150) for i, c in enumerate(cells[:4])})


def seed_tasks(u: dict, dry: bool) -> list[str]:
    ts = CFG["taskSource"] if not dry else {"type": "inline"}
    std = CFG.get("standardTasks", {})
    body: list[str] = []
    if dry or ts["type"] == "inline":
        body = list(u["tasks"])
    elif ts["type"] == "spec-ids":
        rows = spec_rows(ts)
        for rid in expand(u["ids"]):
            if rid not in rows:
                body.append(f"[{rid}] (missing from the spec: raise a blocker)")
            else:
                body.append(render_id_task(ts, rid, rows[rid]))
    elif ts["type"] == "checklist":
        path = ROOT / u["checklist"]
        section = u.get("checklistSection")
        cur = None
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.startswith("#"):
                cur = line.lstrip("#").strip()
            elif (section is None or cur == section) and (m := re.match(r"^\s*- \[[ xX]\] (.+)$", line)):
                body.append(m.group(1).strip())
    elif ts["type"] == "worker-drafted":
        body = [f"[PLAN] Draft this unit's task list from its brief ({u.get('brief', 'see loop.json')}) under "
                f"`## Proposed tasks`, then raise a Needs {USER} (sign-off) item for approval. "
                "Only approved tasks may be added to ## Tasks."]
    else:
        raise SystemExit(f"unknown taskSource.type {ts['type']}")
    if dry:
        return [t if re.match(r"T\d+ ", t) else f"T{i:02d} {t}" for i, t in enumerate(body, 1)]
    first = [t.format(unit=u["id"]) for t in std.get("first", [])]
    if u.get("spike") and std.get("spike"):
        first.append(std["spike"].format(unit=u["id"]))
    last = []
    if std.get("regression") and u is not CFG["units"][0]:
        last.append(std["regression"])
    last += std.get("last", [])
    return [f"T{i:02d} {t}" for i, t in enumerate(first + body + last, 1)]


def unit_folder(u: dict, dry: bool) -> Path:
    if dry:
        return ROOT / CFG["dryRun"]["folder"]
    base = ROOT / CFG.get("unitsRunDir", "runs")
    suffix = f"-{CFG['name']}-{u['id'].lower()}-{u['slug']}"
    existing = sorted(base.glob(f"*{suffix}"))
    return existing[-1] if existing else base / f"{dt.date.today().isoformat()}{suffix}"


def seed_folder(u: dict, dry: bool) -> Path:
    folder = unit_folder(u, dry)
    folder.mkdir(parents=True, exist_ok=True)
    tasks_md = folder / "TASKS.md"
    if not tasks_md.exists():
        lines = ([f"# {u['id']} — {u['name']}", "Status: IN_PROGRESS", "Session: 0", "", "## Tasks"]
                 + [f"- [ ] {t}" for t in seed_tasks(u, dry)] + ["", f"## Needs {USER}", ""])
        tasks_md.write_text("\n".join(lines) + "\n", encoding="utf-8")
        log(f"{u['id']}: seeded {tasks_md.relative_to(ROOT).as_posix()}")
    return folder


# ---------------------------------------------------------------- TASKS.md

def parse_tasks(folder: Path) -> dict:
    p = folder / "TASKS.md"
    info = {"status": "MISSING", "tasks": [], "needs": []}
    if not p.exists():
        return info
    section = None
    for line in p.read_text(encoding="utf-8").splitlines():
        if line.startswith("Status:"):
            v = line.split(":", 1)[1].strip()
            info["status"] = v.split()[0] if v else ""
        elif line.startswith("## "):
            section = line[3:].strip().lower()
        elif section == "tasks" and (m := TASK_RE.match(line)):
            info["tasks"].append((m.group(1), m.group(2), m.group(3).strip()))
        elif section and section.startswith("needs") and (m := NEED_RE.match(line)):
            info["needs"].append((m.group(1), m.group(2), m.group(3).strip()))
    return info


def done_count(info: dict) -> int:
    return sum(1 for s, _, _ in info["tasks"] if s == "x")


def open_needs(info: dict) -> list:
    return [n for n in info["needs"] if n[0] == " "]


def set_session_line(folder: Path, n: int) -> None:
    p = folder / "TASKS.md"
    p.write_text(re.sub(r"(?m)^Session:.*$", f"Session: {n}", p.read_text(encoding="utf-8"), count=1),
                 encoding="utf-8")


# ---------------------------------------------------------------- prompts

def build_prompt(u: dict, folder: Path, session: int, state: dict, dry: bool) -> str:
    rel = folder.relative_to(ROOT).as_posix()
    word = CFG.get("unitWord", "unit")
    parts = [f"You are the worker for {word} {u['id']} — {u['name']} ({CFG['title']}), session {session}.",
             f"Run folder: {rel}", ""]
    if dry:
        parts += ["THIS IS A HARNESS DRY RUN. Touch only files inside the run folder. Do not read or modify",
                  "project code or docs. Do not commit. No gate.", "",
                  f"Read first: {rel}/TASKS.md, {rel}/HANDOFF.md and {rel}/ANSWERS.md if present."]
    else:
        read = CFG.get("readFirst", []) + [f"{rel}/TASKS.md", f"{rel}/HANDOFF.md (if present)",
                                           f"{rel}/RUNLOG.md (if present)"]
        if u.get("brief"):
            read.insert(len(CFG.get("readFirst", [])), u["brief"])
        parts += ["Read first, in order: " + "; ".join(read) + "."]
        prior = [f"{state['units'][p]['folder']}/HANDOFF.md" for p in state["order"][: state["order"].index(u["id"])]
                 if state["units"][p].get("folder") and (ROOT / state["units"][p]["folder"] / "HANDOFF.md").exists()]
        parts += [f"Earlier {word}s' handoffs (read all of them; they describe what already exists):"]
        parts += [f"  - {p}" for p in prior] or [f"  - (none: this is the first {word})"]
    if (folder / "VERIFY-FAIL.md").exists():
        parts += ["", f"The harness rejected the last DONE. Read {rel}/VERIFY-FAIL.md and fix that first."]
    if (folder / "STUCK.md").exists():
        parts += ["", f"The harness STOPPED the last session as stuck. Read {rel}/STUCK.md first. Do not repeat that "
                      "approach: take the smallest path that meets the task as written, or raise a blocker."]
    if (folder / "ANSWERS.md").exists():
        parts += ["", f"{USER}'s answers ({rel}/ANSWERS.md), which are binding:",
                  (folder / "ANSWERS.md").read_text(encoding="utf-8")]
    parts += ["", "Continue from the first unfinished task. Follow your system prompt exactly."]
    return "\n".join(parts)


# ---------------------------------------------------------------- worker backends

def backend_claude(w: dict, dry: bool) -> tuple[list[str], dict, bool]:
    b = w["backends"]["claude"]
    cmd = [b["exe"], "-p", "--output-format", "stream-json", "--verbose",
           "--permission-mode", b.get("permissionMode", "auto"),
           "--append-system-prompt-file", str(SYSTEM_PROMPT)]
    budget = 2 if dry else w.get("maxBudgetUsdPerSession")
    if budget:
        cmd += ["--max-budget-usd", str(budget)]
    if b.get("disallowedTools"):
        cmd += ["--disallowedTools", *b["disallowedTools"]]
    # auto permission mode needs a model that supports it: Haiku headless is denied every write.
    model = w.get("model") or ("sonnet" if dry else None)
    if model:
        cmd += ["--model", model]
    if w.get("effort"):
        cmd += ["--effort", w["effort"]]
    env = dict(os.environ)
    if w.get("subagentModel"):
        env["CLAUDE_CODE_SUBAGENT_MODEL"] = w["subagentModel"]
    return cmd, env, False  # False: the system prompt goes in via a flag, not the stdin prompt


def backend_codex(w: dict, dry: bool) -> tuple[list[str], dict, bool]:
    b = w["backends"]["codex"]
    cmd = [b["exe"], "exec", "--json", "-s", codex_sandbox(), "--skip-git-repo-check"]
    if w.get("model"):
        cmd += ["-m", w["model"]]
    if w.get("effort"):
        cmd += ["-c", f"model_reasoning_effort={w['effort']}"]
    # Codex subagents: [agents] keys in config.toml. Proven via the child thread's rollout in ~/.codex/sessions.
    if w.get("subagentModel"):
        cmd += ["-c", f'agents.default_subagent_model="{w["subagentModel"]}"']
    if w.get("subagentEffort"):
        cmd += ["-c", f'agents.default_subagent_reasoning_effort="{w["subagentEffort"]}"']
    # The user's Codex memory is injected as a developer message that outranks the worker prompt (it once
    # forbade coverage and blocked an AC). Workers run without it, and never write into it.
    if not b.get("useMemories"):
        cmd += ["-c", "memories.use_memories=false", "-c", "memories.generate_memories=false"]
    for kv in b.get("config", []):
        cmd += ["-c", kv]
    cmd.append("-")  # prompt from stdin
    return cmd, dict(os.environ), True  # True: codex has no system-prompt flag, so it is prepended to stdin


def codex_sandbox() -> str:
    """workspace-write makes .git read-only (no commits), so a git-enabled loop needs full access.
    The push guard is then the generator's pre-push hook, not the sandbox's network block."""
    b = CFG["worker"]["backends"]["codex"]
    return b.get("sandbox") or ("danger-full-access" if git_enabled() else "workspace-write")


def backend_command(w: dict, dry: bool) -> tuple[list[str], dict, bool]:
    """Any other agent CLI: loop.json worker.backends.command.cmd, which reads the prompt on stdin. Emitting
    claude-style stream-json on stdout is optional (heartbeats, cost); the harness's own test suite uses it."""
    b = w["backends"]["command"]
    cmd = [sys.executable if c == "{python}" else c for c in b["cmd"]]
    return cmd, dict(os.environ), bool(b.get("prependSystemPrompt", True))


BACKENDS = {"claude": backend_claude, "codex": backend_codex, "command": backend_command}


def parse_event(ev: dict, bs: dict, result: dict) -> None:
    """Pull heartbeat, cost and tokens out of either backend's JSONL events."""
    t = ev.get("type")
    if t == "assistant":  # claude
        for c in ev.get("message", {}).get("content", []):
            if c.get("type") == "tool_use":
                i = c.get("input", {})
                hint = i.get("file_path") or i.get("command") or i.get("description") or ""
                bs["heartbeat"] = {"at": now(), "tool": c.get("name"), "hint": trim(str(hint), 90)}
    elif t == "result":  # claude
        result["cost"] = float(ev.get("total_cost_usd") or 0)
        result["resultText"] = trim(str(ev.get("result") or ""), 400)
    elif t in ("item.started", "item.completed"):  # codex
        item = ev.get("item", {})
        hint = item.get("command") or item.get("path") or item.get("text") or ""
        if isinstance(hint, list):
            hint = " ".join(map(str, hint))
        bs["heartbeat"] = {"at": now(), "tool": item.get("type") or item.get("item_type"), "hint": trim(str(hint), 90)}
        if item.get("type") == "agent_message" and item.get("text"):
            result["resultText"] = trim(item["text"], 400)
    elif t == "turn.completed":  # codex
        # Token caps count uncached tokens only: codex's input_tokens includes cached_input_tokens.
        u = ev.get("usage", {})
        fresh_in = max(0, int(u.get("input_tokens", 0)) - int(u.get("cached_input_tokens", 0)))
        result["tokens"] = result.get("tokens", 0) + fresh_in + int(u.get("output_tokens", 0))


def watchdog_cfg(w: dict) -> dict:
    """worker.watchdog with defaults. silentMinutes: no output event at all (claude emits tool heartbeats every
    30 s, so silence means hung; codex is silent for a whole long command, so it gets more). taskMinutes: one task
    stays the current one without a tick (W2c T02 burned 2.5 h on bisect test runs)."""
    wd = {"silentMinutes": {"claude": 15, "codex": 90, "command": 15}, "taskMinutes": 90, "checkSeconds": 30}
    wd.update(w.get("watchdog") or {})
    return wd


def current_key(info: dict) -> tuple[str, int]:
    cur = next((t[1] for t in info["tasks"] if t[0] == "~"), None) or \
        next((t[1] for t in info["tasks"] if t[0] == " "), "-")
    return cur, done_count(info)


def wide_patterns(u: dict) -> list[str]:
    return [] if u.get("wideOk") else list(CFG.get("delegation", {}).get("widePaths", []))


def wide_snapshot(start_head: str, pats: list[str]) -> dict[str, str]:
    """Content hash of every wide-path file that differs from start_head (committed or not) or is untracked."""
    if not pats or not start_head:
        return {}
    names = set(git("diff", "--name-only", start_head, check=False).splitlines())
    names |= set(git("ls-files", "--others", "--exclude-standard", check=False).splitlines())
    snap = {}
    for n in sorted(names):
        if n and any(fnmatch.fnmatch(n, p) for p in pats):
            f = ROOT / n
            snap[n] = hashlib.sha1(f.read_bytes()).hexdigest() if f.is_file() else "deleted"
    return snap


def gate_running(folder: Path) -> bool:
    m = _read_json_any(folder / GATE_MARKER)
    return bool(m and is_ours(m.get("pid"), "driver"))


def worker_env(env: dict, w: dict, u: dict, folder: Path, session: int, dry: bool) -> dict:
    env = dict(env)
    env.update({k: str(v) for k, v in (w.get("env") or {}).items()})
    env.update(HARNESS_WORKER="1", HARNESS_HOME=str(HERE), HARNESS_UNIT=u["id"], HARNESS_UNIT_FOLDER=str(folder),
               HARNESS_SESSION=str(session), HARNESS_RUN_BUDGET=str(w.get("runBudgetPerTask", 4)),
               HARNESS_DRY="1" if dry else "0")
    env.pop("HARNESS_GATE", None)
    return env


def run_worker(u: dict, folder: Path, session: int, state: dict, dry: bool) -> dict:
    w = resolve_worker(u, state["units"][u["id"]], dry)
    logs = harness_dir(dry) / "logs"
    logs.mkdir(parents=True, exist_ok=True)
    stem = f"{u['id']}-session-{session:02d}"
    prompt = build_prompt(u, folder, session, state, dry)
    cmd, env, prepend_system = BACKENDS[w["backend"]](w, dry)
    env = worker_env(env, w, u, folder, session, dry)
    if prepend_system:
        prompt = SYSTEM_PROMPT.read_text(encoding="utf-8") + "\n\n---\n\n" + prompt
    (logs / f"{stem}.prompt.md").write_text(prompt, encoding="utf-8")
    bs = state["units"][u["id"]]
    result = {"exit": None, "cost": 0.0, "tokens": 0, "timedOut": False, "resultText": "", "killed": None}
    use_git = git_enabled() and not dry
    start_head = git("rev-parse", "HEAD", check=False) if use_git else ""
    pats = wide_patterns(u) if use_git and not bs.get("wideApproved") else []
    wide0 = wide_snapshot(start_head, pats)
    proc = subprocess.Popen(cmd, cwd=ROOT, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                            stdin=subprocess.PIPE, text=True, encoding="utf-8", errors="replace")
    proc.stdin.write(prompt)  # type: ignore[union-attr]  # stdin: no command-line length limit
    proc.stdin.close()  # type: ignore[union-attr]
    bs["workerPid"] = proc.pid
    bs["backend"] = w["backend"]
    save_state(state, dry)
    deadline = time.time() + w.get("sessionTimeoutMinutes", 240) * 60
    wd = watchdog_cfg(w)
    silent_s = float(for_backend(wd["silentMinutes"], w["backend"]) or 0) * 60
    task_s = float(wd["taskMinutes"] or 0) * 60
    last_event = [time.time()]

    def kill(kind: str, why: str) -> None:
        result["killed"] = {"kind": kind, "why": why, "at": now()}
        log(f"{u['id']}: watchdog: {why}; stopping the worker")
        kill_tree(proc.pid)

    def watchdog() -> None:
        key, since, next_check = current_key(parse_tasks(folder)), time.time(), 0.0
        while proc.poll() is None:
            t = time.time()
            if gate_running(folder):  # a long gate is progress: neither stuck nor silent
                since, last_event[0] = t, t
            if t > deadline:
                result["timedOut"] = True
                kill("timeout", f"session timeout ({w.get('sessionTimeoutMinutes', 240)} min)")
                return
            if silent_s and t - last_event[0] > silent_s:
                kill("hung", f"no output from the worker for {int((t - last_event[0]) // 60)} min (hung)")
                return
            if t >= next_check:
                next_check = t + float(wd["checkSeconds"])
                k = current_key(parse_tasks(folder))
                if k != key:
                    key, since = k, t
                elif task_s and key[0] != "-" and t - since > task_s:
                    kill("stuck", f"{key[0]} has been the current task for {int((t - since) // 60)} min "
                                  f"without a tick (limit {wd['taskMinutes']} min)")
                    return
                if pats:
                    snap = wide_snapshot(start_head, pats)
                    hit = [p for p, h in snap.items() if wide0.get(p) != h]
                    if hit:
                        result["wideFiles"] = hit
                        kill("wide", f"wide change without {USER}'s sign-off: {', '.join(hit[:6])}")
                        return
            time.sleep(1)

    threading.Thread(target=watchdog, daemon=True).start()
    last = 0.0
    with (logs / f"{stem}.jsonl").open("w", encoding="utf-8") as f:
        for line in proc.stdout:  # type: ignore[union-attr]
            last_event[0] = time.time()
            f.write(line)
            f.flush()
            try:
                parse_event(json.loads(line), bs, result)
            except (json.JSONDecodeError, AttributeError, TypeError, ValueError):
                pass
            if time.time() - last > 5:
                save_state(state, dry)
                last = time.time()
    result["exit"] = proc.wait()
    bs["workerPid"] = None
    return result


# ---------------------------------------------------------------- verification

def gates_hash() -> str:
    return hashlib.sha1(json.dumps(CFG.get("gates", [])).encode("utf-8")).hexdigest()[:12]


def receipt_path(uid: str) -> Path:
    return harness_dir(False) / "receipts" / f"{uid}.json"


def run_dirs_pathspec() -> list[str]:
    """Changes under the run folders (handoffs, task lists, evidence) never make a gate receipt stale."""
    dirs = {CFG.get("unitsRunDir", "runs"), CFG["harnessDir"]}
    return ["--", "."] + [f":(exclude){d}" for d in sorted(dirs)]


def reusable_receipt(uid: str) -> dict | None:
    """The unit's passing gate receipt, if nothing outside the run folders changed since it was written."""
    if not git_enabled():
        return None
    r = _read_json_any(receipt_path(uid))
    if not r or not r.get("passed") or r.get("gates") != gates_hash() or not r.get("head"):
        return None
    hours = float(CFG["worker"].get("gateReuseHours", 12))
    if dt.datetime.now() - dt.datetime.fromisoformat(r["at"]) > dt.timedelta(hours=hours):
        return None
    same = subprocess.run(["git", "diff", "--quiet", r["head"], "HEAD", *run_dirs_pathspec()], cwd=ROOT,
                          capture_output=True).returncode == 0
    dirty = git("status", "--porcelain", *run_dirs_pathspec(), check=False)
    return r if same and not dirty else None


def _read_json_any(p: Path) -> dict | None:
    try:
        return json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None


def run_gates(uid: str, by: str) -> list[str]:
    """Run every gate once (HARNESS_GATE=1: the project's test runner doesn't charge the run budget) and write
    the unit's gate receipt, so the driver's verification (and any restart) can reuse a passing run."""
    logs = harness_dir(False) / "logs"
    logs.mkdir(parents=True, exist_ok=True)
    env = dict(os.environ, HARNESS_GATE="1")
    head = git("rev-parse", "HEAD", check=False) if git_enabled() else ""
    problems, results = [], []
    for i, gate in enumerate(CFG.get("gates", [])):
        log(f"{uid}: gate {' '.join(gate)} ({by})")
        t0 = time.time()
        # Decode as UTF-8 explicitly: the Windows default (cp1252) crashes on build output such as Next.js's
        # glyphs, leaving stdout None and killing verification (lessons.md, fabricator 2026-09-30).
        g = subprocess.run(gate, cwd=ROOT, capture_output=True, text=True, encoding="utf-8", errors="replace",
                           shell=(os.name == "nt"), env=env)
        name = f"{uid}-gate-{i}.log" if by == "driver" else f"{uid}-wgate-{i}.log"
        (logs / name).write_text(g.stdout + g.stderr, encoding="utf-8")
        results.append({"gate": gate, "exit": g.returncode, "seconds": round(time.time() - t0, 1), "log": name})
        if g.returncode != 0:
            tail = "\n".join((g.stdout + g.stderr).splitlines()[-60:])
            problems.append(f"Gate `{' '.join(gate)}` failed (exit {g.returncode}). Last lines:\n```\n{tail}\n```")
    if head:
        rp = receipt_path(uid)
        rp.parent.mkdir(parents=True, exist_ok=True)
        _write_durable(rp, json.dumps({"unit": uid, "head": head, "gates": gates_hash(), "at": now(), "by": by,
                                       "passed": not problems, "results": results}, indent=2))
    return problems


def verify_done(u: dict, folder: Path, info: dict, dry: bool) -> list[str]:
    d = CFG.get("done", {})
    problems = []
    if any(s != "x" for s, _, _ in info["tasks"]):
        problems.append("Unticked tasks remain under ## Tasks.")
    if open_needs(info):
        problems.append(f"Open ## Needs {USER} items remain.")
    for f in d.get("requireFiles", ["HANDOFF.md", "RUNLOG.md"]):
        if not (folder / f).exists():
            problems.append(f"{f} is missing from the run folder.")
    if dry:
        return problems
    if git_enabled() and d.get("requireCleanTree", True) and git("status", "--porcelain"):
        problems.append("Working tree is not clean; uncommitted changes:\n" + git("status", "--porcelain"))
    if problems:
        return problems  # cheap checks first: never spend a slow gate run on a DONE that is already rejected
    r = reusable_receipt(u["id"])
    if r:
        log(f"{u['id']}: gates passed at {r['head'][:10]} ({r['by']}, {r['at']}); nothing outside the run "
            "folders changed since, so the receipt is reused")
        return problems
    return run_gates(u["id"], "driver")


# ---------------------------------------------------------------- preconditions

def preconditions(dry: bool) -> str | None:
    """Each precondition may carry a `repair` command (for example: launch the editor). A failing check runs its
    repair once and is checked again, so a supervisor restart after a reboot heals the usual blockers itself."""
    if dry:
        return None
    for p in CFG.get("preconditions", []):
        ok = subprocess.run(p["cmd"], cwd=ROOT, capture_output=True, shell=(os.name == "nt")).returncode == 0
        if not ok and p.get("repair"):
            log(f"precondition failed: {p['name']}; repairing with `{' '.join(p['repair'])}`")
            try:
                subprocess.run(p["repair"], cwd=ROOT, capture_output=True, shell=(os.name == "nt"),
                               timeout=int(p.get("repairTimeoutSeconds", 900)))
            except subprocess.TimeoutExpired:
                log(f"repair for {p['name']} timed out")
            ok = subprocess.run(p["cmd"], cwd=ROOT, capture_output=True, shell=(os.name == "nt")).returncode == 0
        if not ok:
            return f"Precondition not met: {p['name']} (`{' '.join(p['cmd'])}` failed)."
    if not git_enabled():
        return None
    g = CFG["git"]
    branch, current = g.get("branch"), git("rev-parse", "--abbrev-ref", "HEAD")
    if not branch or current == branch:
        return None
    if git("status", "--porcelain"):
        return f"On {current} with uncommitted changes; cannot switch to {branch}."
    if git("rev-parse", "--verify", "--quiet", branch, check=False):
        git("switch", branch)
    else:
        git("switch", "-c", branch, g.get("baseBranch", "main"))
        log(f"created {branch} from {g.get('baseBranch', 'main')}")
    return None


# ---------------------------------------------------------------- commands

def pause(state: dict, uid: str, message: str, code: int, dry: bool) -> int:
    state["units"][uid].update(status="PAUSED", message=message)
    # A pause waits for the user: the supervisor must not relaunch it, `run --resume` does after the answer.
    state["driver"].update(status="PAUSED", pid=None, message=f"{uid}: {message}", desired="idle")
    save_state(state, dry)
    log(f"PAUSED {uid}: {message}")
    return code


def escalate(u: dict, bs: dict, why: str, state: dict, dry: bool) -> bool:
    """Move a stuck unit one tier up the ladder instead of pausing. False when there is nowhere to go."""
    w = worker_cfg(u)
    if not can_escalate(w, bs, dry):
        return False
    old = unit_tier(w, bs, dry)
    bs["tierBump"] = bs.get("tierBump", 0) + 1
    bs.update(noProgress=0, crashes=0, verifyFails=0)
    new = unit_tier(w, bs, dry)
    bs.setdefault("escalations", []).append({"at": now(), "from": old, "to": new, "why": why})
    save_state(state, dry)
    log(f"{u['id']}: {why}; escalating tier {old} -> {new}")
    return True


def cmd_run(args) -> int:
    try:
        return _run(args)
    except Exception as e:
        state = load_state(args.dry_run, write=True)
        # desired stays "run": the supervisor relaunches after an unexpected error (with a crash-loop guard).
        state["driver"].update(status="ERROR", pid=None, message=f"{type(e).__name__}: {e}")
        save_state(state, args.dry_run)
        raise


def start_heartbeat(state: dict, dry: bool) -> None:
    """Keep driver.updated fresh while the main thread blocks in a long gate or worker session, so the board and
    the supervisor can tell a live driver from a dead one."""
    def beat() -> None:
        while state["driver"].get("pid") == os.getpid():
            time.sleep(30)
            try:
                save_state(state, dry)
            except (RuntimeError, OSError):  # the main thread was mid-update; the next beat writes it
                pass

    threading.Thread(target=beat, daemon=True).start()


def write_stuck(folder: Path, session: int, killed: dict, info: dict) -> None:
    cur = current_key(info)[0]
    (folder / "STUCK.md").write_text(
        f"# The harness stopped session {session} ({killed['at']})\n\n"
        f"- Why: {killed['why']}.\n"
        f"- Task: {cur}. Its live test runs this session are in RUN-LEDGER.json.\n"
        "- Next session: read HANDOFF.md and the logs and reports that already exist. Do not repeat the approach "
        "that stalled. Take the smallest path that meets the task as written, or raise a blocker with what you "
        "learned. This file is deleted once a task is ticked.\n", encoding="utf-8")


def _run(args) -> int:
    dry = args.dry_run
    state = load_state(dry, write=True)
    drv = state["driver"]
    if drv.get("pid") and drv["pid"] != os.getpid() and is_ours(drv["pid"], "driver") and drv["status"] == "RUNNING":
        log(f"another driver (pid {drv['pid']}) is running")
        return 5
    for uid, bs in state["units"].items():
        if is_ours(bs.get("workerPid"), "worker"):
            log(f"{uid}: killing orphaned worker pid {bs['workerPid']} left by a dead driver")
            kill_tree(bs["workerPid"])
        bs["workerPid"] = None
    drv["desired"] = "run"  # until a pause, COMPLETE or `stop`: the supervisor keeps this driver alive
    problem = preconditions(dry)
    if problem:
        drv.update(status="BLOCKED", message=problem, pid=None)
        save_state(state, dry)
        log(problem)
        return 5
    drv.update(status="RUNNING", pid=os.getpid(), message="")
    save_state(state, dry)
    start_heartbeat(state, dry)
    epic_cap = CFG["worker"].get("totalBudgetUsd")

    for uid in state["order"]:
        u, bs = unit_cfg(uid), state["units"][uid]
        w = worker_cfg(u)
        if bs["status"] == "DONE":
            continue
        if bs["status"] == "PAUSED":
            if not args.resume:
                drv.update(status="PAUSED", pid=None, message=f"{uid}: {bs['message']}", desired="idle")
                save_state(state, dry)
                log(f"{uid} is paused: {bs['message']} (answer, then run --resume)")
                return 3
            bs.update(status="RUNNING", message="", noProgress=0, crashes=0, verifyFails=0)
            args.resume = False
        folder = seed_folder(u, dry)
        bs["folder"] = folder.relative_to(ROOT).as_posix()
        state["current"] = uid
        bs["status"] = "RUNNING"
        save_state(state, dry)

        while True:
            before = parse_tasks(folder)
            if before["status"] == "DONE" and not (folder / "VERIFY-FAIL.md").exists():
                if not verify_done(u, folder, before, dry):
                    bs.update(status="DONE", message=f"verified {now()}", heartbeat=None)
                    save_state(state, dry)
                    log(f"{uid}: DONE on disk, verified without a new session")
                    break
            spent = sum(x.get("costUsd", 0) for x in state["units"].values())
            if epic_cap and not dry and spent >= epic_cap:
                return pause(state, uid, f"total budget reached (${spent:.2f} of ${epic_cap})", 4, dry)
            # Codex reports tokens, not dollars, so USD caps never fire for it. Token caps cover every backend
            # and count uncached tokens only (cache hits are excluded).
            used = sum(x.get("tokens", 0) for x in state["units"].values())
            tok_cap = CFG["worker"].get("totalTokens")
            if tok_cap and used >= tok_cap:
                return pause(state, uid, f"total token budget reached ({used:,} of {tok_cap:,} uncached)", 4, dry)
            bs["sessions"] += 1
            set_session_line(folder, bs["sessions"])
            rw = resolve_worker(u, bs, dry)
            bs.update(tier=rw["resolvedTier"], model=rw.get("model") or "default")
            log(f"{uid}: starting {w['backend']} worker session {bs['sessions']} "
                f"(tier={rw['resolvedTier'] or '-'} model={rw.get('model') or 'default'})")
            res = run_worker(u, folder, bs["sessions"], state, dry)
            killed = res.get("killed")
            bs["costUsd"] = round(bs["costUsd"] + res["cost"], 4)
            bs["tokens"] = bs.get("tokens", 0) + res.get("tokens", 0)
            bs["lastExit"] = {"code": res["exit"], "timedOut": res["timedOut"], "at": now(), "result": res["resultText"],
                              "killed": killed}
            after = parse_tasks(folder)
            sess_cap = w.get("maxTokensPerSession")
            if sess_cap and res.get("tokens", 0) > sess_cap:
                save_state(state, dry)
                return pause(state, uid, f"session used {res['tokens']:,} uncached tokens, over the "
                                         f"{sess_cap:,} per-session cap (codex reports usage only at the end)", 4, dry)
            log(f"{uid}: session {bs['sessions']} exit={res['exit']} status={after['status']} "
                f"done={done_count(after)}/{len(after['tasks'])} cost=${res['cost']:.2f}"
                + (f" killed={killed['kind']}" if killed else ""))

            if killed and killed["kind"] == "wide":
                files = ", ".join(res.get("wideFiles", [])[:8])
                return pause(state, uid, f"wide change without {USER}'s sign-off ({files}). Approve: answer {uid} "
                                         f"WIDE \"<words>\"; decline: answer {uid} WIDE-NO \"<words>\" (the next "
                                         "worker reverts it); then run --resume", 3, dry)

            if open_needs(after) or after["status"].startswith("NEEDS"):
                items = "; ".join(f"{n[1]} {n[2]}" for n in open_needs(after)) or "status NEEDS"
                return pause(state, uid, f"needs {USER}: {items}", 3, dry)

            if after["status"] == "DONE" and not killed:
                problems = verify_done(u, folder, after, dry)
                if not problems:
                    (folder / "VERIFY-FAIL.md").unlink(missing_ok=True)
                    (folder / "STUCK.md").unlink(missing_ok=True)
                    bs.update(status="DONE", message=f"verified {now()}", heartbeat=None)
                    save_state(state, dry)
                    log(f"{uid}: DONE (verified)")
                    break
                (folder / "VERIFY-FAIL.md").write_text(
                    f"# Harness verification failed ({now()})\n\n" + "\n\n".join(f"- {p}" for p in problems) + "\n",
                    encoding="utf-8")
                bs["verifyFails"] = bs.get("verifyFails", 0) + 1
                log(f"{uid}: DONE rejected: {len(problems)} problem(s)")
                if bs["verifyFails"] > w.get("maxSessionsWithoutProgress", 2):
                    if escalate(u, bs, "verification keeps failing", state, dry):
                        continue
                    return pause(state, uid, "verification keeps failing, see VERIFY-FAIL.md", 4, dry)
                continue

            progressed = done_count(after) > done_count(before)
            if progressed:
                (folder / "STUCK.md").unlink(missing_ok=True)
            if killed and killed["kind"] in ("stuck", "hung"):
                write_stuck(folder, bs["sessions"], killed, after)
            # A stuck kill is a stall, not a crash: it counts toward noProgress only.
            crashed = (res["exit"] not in (0, None) or res["timedOut"]) and not (killed and killed["kind"] == "stuck")
            bs["noProgress"] = 0 if progressed else bs["noProgress"] + 1
            bs["crashes"] = bs["crashes"] + 1 if crashed else 0
            save_state(state, dry)
            limit = w.get("maxSessionsWithoutProgress", 2)
            if bs["noProgress"] >= limit:
                why = f"stalled: {bs['noProgress']} sessions without a ticked task"
                if escalate(u, bs, why, state, dry):
                    continue
                return pause(state, uid, why, 4, dry)
            if bs["crashes"] >= limit:
                why = f"worker crashed {bs['crashes']} times in a row"
                if escalate(u, bs, why, state, dry):
                    continue
                return pause(state, uid, why, 4, dry)

    state["current"] = None
    drv.update(status="COMPLETE", pid=None, message=f"All {CFG.get('unitWord', 'unit')}s DONE and verified.",
               desired="idle")
    save_state(state, dry)
    log("complete")
    return 0


def cmd_gate(args) -> int:
    """The worker's one regression run: every gate, on a clean committed tree, at most worker.gateRunsPerSession
    times per session. A pass writes the gate receipt the driver reuses, so DONE verification costs no rerun."""
    state = load_state(False)
    uid = os.environ.get("HARNESS_UNIT") or state.get("current")
    if not uid:
        log("no current unit (run this from a worker session, or while the loop is on a unit)")
        return 2
    if os.environ.get("HARNESS_DRY") == "1":
        log("dry run: no gate")
        return 0
    if not git_enabled():
        log("git is off for this loop, so there is no receipt: the driver runs the gates after DONE")
        return 2
    dirty = git("status", "--porcelain")
    if dirty:
        log("refused: commit first. The gate only counts for committed code (uncommitted: "
            + ", ".join(dirty.splitlines()[:8]) + ")")
        return 2
    r = reusable_receipt(uid)
    if r:
        log(f"gates already passed for this code ({r['head'][:10]}, {r['at']}); nothing to run")
        return 0
    folder = os.environ.get("HARNESS_UNIT_FOLDER")
    limit = int(CFG["worker"].get("gateRunsPerSession", 2))
    lp = Path(folder) / "RUN-LEDGER.json" if folder else None
    session = os.environ.get("HARNESS_SESSION", "0")
    if lp and limit > 0:
        done = ((_read_json_any(lp) or {}).get(session, {}).get("_gate") or {}).get("runs", 0)
        if done >= limit:
            log(f"refused: this session already ran the gate {done} times (limit {limit}). Read the gate "
                "logs you have, fix what they show, set DONE and let the harness verify, or record the gap.")
            return 3
    # While the gate runs (35+ min on a live editor), the watchdog must neither call the worker stuck nor silent:
    # killing it mid-gate cuts off a live test run, which can wedge the tool it drives.
    marker = Path(folder) / GATE_MARKER if folder else None
    if marker:
        marker.write_text(json.dumps({"pid": os.getpid(), "at": now()}), encoding="utf-8")
    try:
        problems = run_gates(uid, "worker")
    finally:
        if marker:
            marker.unlink(missing_ok=True)
    if lp and limit > 0:  # charged only for a completed run: a gate that was cut off costs no slot
        ledger = _read_json_any(lp) or {}
        gate = ledger.setdefault(session, {}).setdefault("_gate", {"runs": 0, "labels": []})
        gate["runs"] += 1
        gate["labels"].append(f"{dt.datetime.now():%H:%M} gate at {git('rev-parse', '--short', 'HEAD')}: "
                              + ("pass" if not problems else "fail"))
        _write_durable(lp, json.dumps(ledger, indent=1))
    for p in problems:
        print(p)
    log(f"{uid}: gate {'PASS: receipt written; the harness reuses it if nothing outside the run folders changes' if not problems else 'FAIL'}")
    return 0 if not problems else 1


def cmd_answer(args) -> int:
    state = load_state(args.dry_run, write=True)
    bs = state["units"].get(args.unit, {})
    folder = bs.get("folder")
    if not folder:
        log(f"{args.unit} has no run folder yet")
        return 2
    p = ROOT / folder / "ANSWERS.md"
    head = "" if p.exists() else f"# {args.unit} — {USER}'s answers (binding)\n\n"
    text = args.text
    if args.need == "WIDE":
        bs["wideApproved"] = True
        text += f"\n\n({USER} approved wide changes for {args.unit}: the harness no longer stops on them.)"
    elif args.need == "WIDE-NO":
        text += (f"\n\n({USER} declined the wide change. Revert every change to the wide paths that has no approval, "
                 "keep the change inside this unit's own scope, or raise a blocker.)")
    with p.open("a", encoding="utf-8") as f:
        f.write(f"{head}## {args.need} — {now()}\n\n{text}\n\n")
    save_state(state, args.dry_run)
    log(f"recorded answer for {args.unit} {args.need} in {folder}/ANSWERS.md")
    return 0


# ---------------------------------------------------------------- recover

def session_costs(uid: str, dry: bool) -> tuple[float, int, int]:
    """(cost, priced sessions, unpriced sessions) from the per-session JSONL logs: the last claude `result`
    event carries the cumulative total_cost_usd. Codex sessions and sessions cut off before their result
    (a crash) are unpriced."""
    total, priced, unpriced = 0.0, 0, 0
    for f in sorted((harness_dir(dry) / "logs").glob(f"{uid}-session-*.jsonl")):
        cost = None
        try:
            for line in f.read_text(encoding="utf-8", errors="replace").splitlines():
                if '"total_cost_usd"' not in line:
                    continue
                try:
                    ev = json.loads(line)
                except ValueError:
                    continue
                if ev.get("type") == "result" and ev.get("total_cost_usd") is not None:
                    cost = float(ev["total_cost_usd"])
        except OSError:
            pass
        if cost is None:
            unpriced += 1
        else:
            total += cost
            priced += 1
    return round(total, 4), priced, unpriced


def rebuild_state(dry: bool) -> dict:
    """A state rebuilt from the run folders and logs alone, for `recover`.
    DONE on disk stays DONE without re-verification (a crashed worker may have left the tree dirty, and
    re-verifying a finished unit against it would fail and spend a session). Open Needs make a unit PAUSED,
    any ticked task or recorded session makes it RUNNING, anything else stays PENDING."""
    state = fresh_state(dry)
    state["current"] = None
    for u in units(dry):
        uid = u["id"]
        bs = state["units"][uid]
        folder = unit_folder(u, dry)
        tasks_md = folder / "TASKS.md"
        if not tasks_md.exists():
            continue
        bs["folder"] = folder.relative_to(ROOT).as_posix()
        info = parse_tasks(folder)
        m = re.search(r"(?m)^Session:\s*(\d+)", tasks_md.read_text(encoding="utf-8"))
        sessions = int(m.group(1)) if m else 0
        cost, priced, unpriced = session_costs(uid, dry)
        bs.update(sessions=max(sessions, priced + unpriced), costUsd=cost)
        notes = []
        if info["status"] == "DONE":
            bs["status"] = "DONE"
            notes.append("DONE on disk (recovered, not re-verified)")
        elif open_needs(info) or info["status"].startswith("NEEDS"):
            bs["status"] = "PAUSED"
            items = "; ".join(f"{n[1]} {n[2]}" for n in open_needs(info)) or "status NEEDS"
            notes.append(f"needs {USER}: {items}")
        elif done_count(info) or sessions:
            bs["status"] = "RUNNING"
        if unpriced:
            bs["costUnknownSessions"] = unpriced
            notes.append(f"{unpriced} session(s) had no cost record (cut off or codex); spend undercounts")
        bs["message"] = "; ".join(notes)
        if bs["status"] != "DONE" and state["current"] is None:
            state["current"] = uid
    state["driver"].update(status="IDLE", pid=None, message=f"state rebuilt by `recover` at {now()}")
    return state


def cmd_recover(args) -> int:
    """Rebuild state.json from disk after a crash. Refuses while a driver for this state is alive."""
    dry = args.dry_run
    p = state_path(dry)
    current = _read_json(p)
    if current is not None and not args.force:
        log("state.json is readable; nothing to recover (pass --force to rebuild it from disk anyway)")
        return 0
    for known in (current, _read_json(p.with_suffix(".bak"))):
        if known and known["driver"].get("status") == "RUNNING" and pid_alive(known["driver"].get("pid")):
            log(f"a driver (pid {known['driver']['pid']}) is still running; stop it before recovering")
            return 5
    if p.exists():
        backup = p.with_name(f"state.corrupt-{dt.datetime.now().strftime('%Y%m%d-%H%M%S')}.json")
        shutil.copy(p, backup)
        log(f"kept the old state as {backup.name}")
    state = rebuild_state(dry)
    save_state(state, dry)
    for uid in state["order"]:
        bs = state["units"][uid]
        log(f"{uid}: {bs['status']} sessions={bs['sessions']} ${bs['costUsd']:.2f}"
            + (f" ({bs['message']})" if bs.get("message") else ""))
    log("recovered; continue with `run` (or `run --resume` when a unit is PAUSED and answered)")
    return 0


def driver_alive(state: dict) -> bool:
    return is_ours(state["driver"].get("pid"), "driver")


def cmd_status(args) -> int:
    state = load_state(args.dry_run)
    d = state["driver"]
    shown = d["status"]
    if shown == "RUNNING" and not driver_alive(state):
        shown = "STOPPED (driver pid is dead; the supervisor relaunches it if desired=run)"
    print(f"driver: {shown}  desired={d.get('desired', 'idle')}  {d.get('message', '')}")
    for uid in state["order"]:
        bs = state["units"][uid]
        line = f"{uid:4} {bs['status']:8} sessions={bs['sessions']} ${bs['costUsd']:.2f}"
        if bs.get("model"):
            line += f" {bs.get('tier') or '-'}:{bs['model']}"
        if bs.get("folder"):
            info = parse_tasks(ROOT / bs["folder"])
            cur = next((t for t in info["tasks"] if t[0] == "~"), next((t for t in info["tasks"] if t[0] == " "), None))
            line += f" tasks={done_count(info)}/{len(info['tasks'])}"
            if cur:
                line += f" current={cur[1]} {trim(cur[2], 60)}"
            for n in open_needs(info):
                line += f"\n      OPEN {n[1]} {n[2]}"
        print(line + (f"\n      {bs['message']}" if bs.get("message") else ""))
    return 0


def cmd_stop(args) -> int:
    """Cancel the loop: kill the driver and the worker, and record desired=stop so the supervisor leaves it."""
    dry = args.dry_run
    state = load_state(dry, write=True)
    drv = state["driver"]
    pids = [(drv.get("pid"), "driver")] + [(bs.get("workerPid"), "worker") for bs in state["units"].values()]
    for pid, kind in pids:
        if pid and pid != os.getpid() and is_ours(pid, kind):
            kill_tree(pid)
            log(f"stopped the {kind} (pid {pid})")
        elif pid and pid_alive(pid):
            log(f"left pid {pid} alone: it is alive but no longer the harness {kind} ({proc_image(pid) or '?'})")
    state = load_state(dry, write=True)  # re-read: the dying driver may have written last
    for bs in state["units"].values():
        bs["workerPid"] = None
        if bs["status"] == "RUNNING":
            bs["status"] = "PENDING" if not bs.get("sessions") else "STOPPED"
            bs["message"] = f"stopped by {args.by} {now()}"
    state["driver"].update(status="STOPPED", pid=None, desired="stop", message=f"stopped by {args.by}: {args.reason}")
    save_state(state, dry)
    log(f"loop stopped ({args.reason}); `run` starts it again")
    return 0


# ---------------------------------------------------------------- supervisor

def _spawn_detached(argv: list[str], logfile: Path) -> int:
    """Start a process that outlives the caller: its own process group, out of the caller's job object (a Claude
    session's background tasks are killed with it), output appended to logfile."""
    logfile.parent.mkdir(parents=True, exist_ok=True)
    out = open(logfile, "a", encoding="utf-8")
    kw: dict = {"cwd": ROOT, "stdout": out, "stderr": subprocess.STDOUT, "stdin": subprocess.DEVNULL}
    if os.name == "nt":
        base = 0x00000008 | 0x00000200  # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
        try:
            return subprocess.Popen(argv, creationflags=base | 0x01000000, **kw).pid  # + CREATE_BREAKAWAY_FROM_JOB
        except OSError:
            return subprocess.Popen(argv, creationflags=base, **kw).pid  # the job forbids breakaway
    return subprocess.Popen(argv, start_new_session=True, **kw).pid


def board_up(port: int) -> bool:
    try:
        urllib.request.urlopen(f"http://127.0.0.1:{port}/{HERE.relative_to(ROOT).as_posix()}/loop.json", timeout=3)
        return True
    except OSError:
        return False


def cmd_supervise(args) -> int:
    """One-shot health check, run every few minutes by the Scheduled Task (and safe to run by hand):
    relaunch a dead driver the user still wants running, and the board. It never starts a loop that was
    paused, completed or stopped. More than 3 relaunches in 30 min means a crash loop: it gives up and says so."""
    hd = harness_dir(False)
    slog = hd / "supervisor.log"

    def note(msg: str) -> None:
        slog.parent.mkdir(parents=True, exist_ok=True)
        with slog.open("a", encoding="utf-8") as f:
            f.write(f"[{now()}] {msg}\n")
        log(msg)

    state = load_state(False)
    drv = state["driver"]
    port = int(CFG.get("board", {}).get("port", 8765))
    if CFG.get("board", {}).get("autoServe", True) and drv.get("desired") == "run" and not board_up(port):
        pid = _spawn_detached([sys.executable, str(HERE / "harness.py"), "serve"], hd / "board.out.log")
        note(f"board was down; started it (pid {pid})")
    if drv.get("desired") != "run":
        print(f"desired={drv.get('desired', 'idle')} status={drv['status']}: nothing to supervise")
        return 0
    if driver_alive(state):
        return 0
    sup = state.setdefault("supervisor", {"restarts": []})
    cutoff = dt.datetime.now() - dt.timedelta(minutes=30)
    recent = [t for t in sup.get("restarts", []) if dt.datetime.fromisoformat(t) > cutoff]
    if len(recent) >= 3:
        drv.update(status="ERROR", desired="halted",
                   message=f"supervisor gave up: the driver died {len(recent)} times in 30 min; see "
                           f"{(hd / 'driver.out.log').relative_to(ROOT).as_posix()}. Fix it, then `run`.")
        save_state(state, False)
        note(drv["message"])
        return 1
    recent.append(now())
    sup["restarts"] = recent
    save_state(state, False)
    pid = _spawn_detached([sys.executable, str(HERE / "harness.py"), "run"], hd / "driver.out.log")
    note(f"driver was dead (last status {drv['status']}: {trim(drv.get('message') or '-', 120)}); relaunched it "
         f"(pid {pid})")
    return 0


def cmd_start(args) -> int:
    """Launch the driver detached (it survives this shell and any Claude session) plus the board, and return."""
    state = load_state(False, write=True)
    if driver_alive(state):
        log(f"the driver is already running (pid {state['driver']['pid']})")
        return 0
    state["driver"]["desired"] = "run"
    state.setdefault("supervisor", {})["restarts"] = []
    save_state(state, False)
    hd = harness_dir(False)
    pid = _spawn_detached([sys.executable, str(HERE / "harness.py"), "run"] + (["--resume"] if args.resume else []),
                          hd / "driver.out.log")
    log(f"driver started detached (pid {pid}); output: {(hd / 'driver.out.log').relative_to(ROOT).as_posix()}")
    port = int(CFG.get("board", {}).get("port", 8765))
    if CFG.get("board", {}).get("autoServe", True) and not board_up(port):
        _spawn_detached([sys.executable, str(HERE / "harness.py"), "serve"], hd / "board.out.log")
    log(f"board: http://127.0.0.1:{port}/{HERE.relative_to(ROOT).as_posix()}/status.html")
    return 0


def task_name() -> str:
    return f"harness-{CFG['name']}-supervisor"


def cmd_supervisor(args) -> int:
    if os.name != "nt":
        print(f"Add to crontab -e:\n*/{args.every} * * * * cd {ROOT} && {sys.executable} {HERE / 'harness.py'} supervise")
        return 0
    if args.action == "status":
        r = subprocess.run(["schtasks", "/Query", "/TN", task_name(), "/V", "/FO", "LIST"], capture_output=True,
                           text=True, errors="replace")
        print(r.stdout or r.stderr)
        return r.returncode
    if args.action == "uninstall":
        r = subprocess.run(["schtasks", "/Delete", "/TN", task_name(), "/F"], capture_output=True, text=True,
                           errors="replace")
        print((r.stdout or r.stderr).strip())
        return r.returncode
    pyw = Path(sys.executable).with_name("pythonw.exe")
    exe = pyw if pyw.exists() else Path(sys.executable)  # pythonw: no console window flashing every few minutes
    tr = f'"{exe}" "{HERE / "harness.py"}" supervise'
    r = subprocess.run(["schtasks", "/Create", "/F", "/SC", "MINUTE", "/MO", str(args.every), "/TN", task_name(),
                        "/TR", tr], capture_output=True, text=True, errors="replace")
    print((r.stdout or r.stderr).strip())
    if r.returncode == 0:
        print(f"{task_name()}: every {args.every} min while you are logged on (so after a reboot too), it relaunches "
              "a dead driver whose desired state is run. Cancel the loop with `harness.py stop`, never by killing "
              "the process, or it is relaunched.")
    return r.returncode


def cmd_validate(args) -> int:
    missing = [k for k in ("name", "title", "harnessDir", "worker", "units", "dryRun", "taskSource") if k not in CFG]
    if missing:
        print(f"loop.json is missing keys: {missing}")
        return 1
    for b in {worker_cfg(u)["backend"] for u in CFG["units"]}:
        exe = CFG["worker"]["backends"][b]["exe"]
        print(f"backend {b}: {exe} {'OK' if Path(exe).exists() else 'NOT FOUND'}")
    codex_slugs = codex_models()
    total, warnings = 0, []
    for u in CFG["units"] + [CFG["dryRun"]]:
        dry = u is CFG["dryRun"]
        w = worker_cfg(u)
        t = seed_tasks(u, dry)
        total += 0 if dry else len(t)
        bad = [x for x in t if "missing from the spec" in x]
        rw = resolve_worker(u, None, dry)
        steps = [rw]  # every tier the unit could escalate to must resolve too
        if w.get("escalate") and rw["resolvedTier"] and not dry:
            lad = ladder(w)
            steps += [resolve_worker(u, {"tierBump": i}, dry) for i in range(1, len(lad) - lad.index(rw["resolvedTier"]))]
        path = " -> ".join(f"{s['resolvedTier'] or '-'}:{s.get('model') or 'default'}" for s in steps)
        print(f"{u['id']:4} {len(t):3} tasks  backend={w['backend']} {path}"
              + (f"  subagent={rw['subagentModel']}" if rw.get("subagentModel") else "")
              + (f"  MISSING: {bad}" if bad else ""))
        if w.get("tier") and w["tier"] not in w.get("tiers", {}):
            warnings.append(f"{u['id']}: tier {w['tier']!r} is not defined in worker.tiers")
        if w["backend"] == "codex" and codex_slugs is not None:
            for m in {s.get("model") for s in steps} | {rw.get("subagentModel")}:
                if m and m not in codex_slugs:
                    warnings.append(f"{u['id']}: {m!r} is not a codex model here (known: {', '.join(sorted(codex_slugs))})")
    print(f"total {total} tasks")
    wk = CFG["worker"]
    wd = watchdog_cfg(wk)
    print(f"watchdog: silent {wd['silentMinutes']} min, one task {wd['taskMinutes']} min; run budget "
          f"{wk.get('runBudgetPerTask', 4)} live runs per task per session; gate {wk.get('gateRunsPerSession', 2)} "
          f"runs per session, receipts reused for {wk.get('gateReuseHours', 12)} h")
    wide = CFG.get("delegation", {}).get("widePaths", [])
    print(f"wide paths ({len(wide)}): {', '.join(wide) or 'none: the wide-change tripwire is off'}"
          + (f"; pre-approved for {', '.join(u['id'] for u in CFG['units'] if u.get('wideOk'))}"
             if any(u.get("wideOk") for u in CFG["units"]) else ""))
    if not (HERE / "run_budget.py").exists():
        warnings.append("run_budget.py is missing next to harness.py (regenerate or `new_harness.py --upgrade`)")
    for p in CFG.get("preconditions", []):
        if not p.get("repair"):
            print(f"note: precondition {p['name']!r} has no repair command; after a reboot the supervisor can only "
                  "retry it")
    if git_enabled() and any(worker_cfg(u)["backend"] == "codex" for u in CFG["units"]):
        if codex_sandbox() != "danger-full-access":
            warnings.append(f"codex sandbox {codex_sandbox()!r} blocks .git writes: workers can't commit "
                            "(use danger-full-access; the pre-push hook guards pushes)")
        hook = ROOT / ".git" / "hooks" / "pre-push"
        if not CFG["git"].get("allowPush") and not (hook.exists() and "harness" in hook.read_text(errors="replace")):
            warnings.append("codex workers run with full access but .git/hooks/pre-push is not the harness push "
                            "guard; regenerate or install it")
    if codex_slugs is None and any(worker_cfg(u)["backend"] == "codex" for u in CFG["units"]):
        print("warning: ~/.codex/models_cache.json not readable; codex model names were not checked")
    for msg in warnings:
        print(f"warning: {msg}")
    return 1 if warnings else 0


def codex_models() -> set[str] | None:
    """Model slugs this machine's codex knows (listed ones only). The cache is UTF-8, not cp1252."""
    try:
        d = json.loads((Path.home() / ".codex" / "models_cache.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    ms = d.get("models", []) if isinstance(d, dict) else d
    return {m["slug"] for m in ms if isinstance(m, dict) and m.get("slug") and m.get("visibility", "list") == "list"}


class _NoCache(http.server.SimpleHTTPRequestHandler):
    def end_headers(self) -> None:
        self.send_header("Cache-Control", "no-store")
        super().end_headers()

    def log_message(self, *a) -> None:
        pass


def cmd_serve(args) -> int:
    port = args.port or CFG.get("board", {}).get("port", 8765)
    class _Exclusive(http.server.ThreadingHTTPServer):
        # Windows SO_REUSEADDR lets a second server bind a port already in use and silently lose every
        # request to the first one (another harness's board). Refuse instead.
        allow_reuse_address = False

    try:
        srv = _Exclusive(("127.0.0.1", port), functools.partial(_NoCache, directory=str(ROOT)))
    except OSError as e:
        log(f"port {port} is in use ({e}); another board is probably running. Use --port N.")
        return 2
    log(f"board: http://127.0.0.1:{port}/{HERE.relative_to(ROOT).as_posix()}/status.html")
    srv.serve_forever()
    return 0


def main() -> int:
    for s in (sys.stdout, sys.stderr):
        if s is not None:  # pythonw (the supervisor's Scheduled Task) has no console streams
            s.reconfigure(encoding="utf-8", errors="replace")  # Windows consoles default to cp1252
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    r = sub.add_parser("run")
    r.add_argument("--resume", action="store_true")
    r.add_argument("--dry-run", action="store_true")
    a = sub.add_parser("answer")
    a.add_argument("unit")
    a.add_argument("need")
    a.add_argument("text")
    a.add_argument("--dry-run", action="store_true")
    s = sub.add_parser("status")
    s.add_argument("--dry-run", action="store_true")
    v = sub.add_parser("serve")
    v.add_argument("--port", type=int, default=None)
    sub.add_parser("validate")
    rc = sub.add_parser("recover")
    rc.add_argument("--force", action="store_true", help="rebuild even when state.json is readable")
    rc.add_argument("--dry-run", action="store_true")
    sub.add_parser("gate")
    st = sub.add_parser("stop")
    st.add_argument("--reason", default="cancelled")
    st.add_argument("--by", default="the orchestrator")
    st.add_argument("--dry-run", action="store_true")
    sub.add_parser("supervise")
    sa = sub.add_parser("start")
    sa.add_argument("--resume", action="store_true")
    sv = sub.add_parser("supervisor")
    sv.add_argument("action", choices=["install", "uninstall", "status"])
    sv.add_argument("--every", type=int, default=5, help="minutes between checks (install)")
    args = ap.parse_args()
    return {"run": cmd_run, "answer": cmd_answer, "status": cmd_status, "serve": cmd_serve,
            "validate": cmd_validate, "recover": cmd_recover, "gate": cmd_gate, "stop": cmd_stop, "supervise": cmd_supervise,
            "start": cmd_start, "supervisor": cmd_supervisor}[args.cmd](args)


if __name__ == "__main__":
    sys.exit(main())
